// Scratch check, not part of the repo: import boundary at exactly 1 MiB.
const path = require('path');
const b = require(path.resolve('<thư-mục-tạm>'));

console.log('node', process.version, '| MAX_IMPORT_BYTES =', b.MAX_IMPORT_BYTES);

// A valid backup, padded with trailing spaces (still valid JSON) to an exact byte count.
function backupOfSize(bytes) {
  const base = b.toBackupText([{ id: 'a1', title: 'Mua sữa', done: false, createdAt: 1761523200000 }]);
  const baseBytes = Buffer.byteLength(base, 'utf8');
  return base + ' '.repeat(bytes - baseBytes);
}

async function run(bytes) {
  const blob = new Blob([backupOfSize(bytes)], { type: 'application/json' });
  let textCalls = 0;
  const file = {
    size: blob.size,
    text: () => { textCalls += 1; return blob.text(); },
  };
  const store = {
    readError: false,
    replaced: null,
    save: () => 'saved',
    replace(todos) { this.replaced = todos; return 'saved'; },
  };
  let asked = 0;
  const current = [];
  const result = await b.importBackup({ store, current, file, ask: async () => { asked += 1; return true; } });
  console.log(`\n--- file of ${bytes} bytes (blob.size = ${blob.size}) ---`);
  console.log('file.text() calls :', textCalls);
  console.log('message           :', result.message);
  console.log('todos returned    :', result.todos.length, result.todos === current ? '(current list, unchanged)' : '(new list)');
  console.log('store.replace     :', store.replaced === null ? 'not called' : `called with ${store.replaced.length} todo(s)`);
  console.log('ask() calls       :', asked);
  return { textCalls, result, store };
}

(async () => {
  const over = await run(1048577);
  const at = await run(1048576);
  const okOver = over.textCalls === 0 && over.result.message === b.MESSAGES.fileTooBig && over.store.replaced === null;
  const okAt = at.textCalls === 1 && at.result.message === b.fill(b.MESSAGES.imported, { n: 1 });
  console.log(`\n1,048,577 refused before read: ${okOver ? 'PASS' : 'FAIL'}`);
  console.log(`1,048,576 read and imported : ${okAt ? 'PASS' : 'FAIL'}`);
  process.exitCode = okOver && okAt ? 0 : 1;
})();

